const $=s=>document.querySelector(s),money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=[{id:1,name:'Ana',title:'Manter a luz acesa em casa.',category:'Contas da casa',value:286.40,paid:0,story:'Um mês difícil apertou o orçamento. Quitar a conta de luz traz mais tranquilidade para mim e meus dois filhos.'},{id:2,name:'Marcos',title:'Um lar para seguir em frente.',category:'Moradia',value:950,paid:200,story:'Estou recomeçando no trabalho e preciso de uma ajuda com o aluguel que ficou para trás.'},{id:3,name:'Lúcia',title:'Cuidar da saúde, sem adiar.',category:'Saúde',value:420,paid:0,story:'Preciso quitar uma dívida com o tratamento dentário. Essa ajuda vai aliviar as despesas deste mês.'},{id:4,name:'Pedro',title:'Voltar a estudar com tranquilidade.',category:'Educação',value:680,paid:0,story:'Uma mensalidade atrasada se tornou um obstáculo. Quero colocar tudo em dia e seguir meus estudos.'},{id:5,name:'Rita',title:'Sair dos juros e respirar de novo.',category:'Cartão e empréstimos',value:1340,paid:340,story:'As compras essenciais viraram uma dívida no cartão. Estou reorganizando as contas para recomeçar.'},{id:6,name:'José',title:'Recuperar as ferramentas de trabalho.',category:'Outras dívidas',value:360,paid:0,story:'Ficou uma dívida do conserto das minhas ferramentas. Quitar esse valor me ajuda a retomar os serviços.'}];
let debts;try{debts=JSON.parse(localStorage.getItem('recomeco-v1'))||initial;if(!Array.isArray(debts))debts=initial}catch{debts=initial}let filter='Todas',selected;const categories=['Todas','Contas da casa','Moradia','Saúde','Educação','Cartão e empréstimos','Outras dívidas'];
function notify(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),4500)}
function save(){try{localStorage.setItem('recomeco-v1',JSON.stringify(debts))}catch{notify('Seu navegador não permitiu salvar. Os dados durarão até recarregar a página.')}}
function render(){const query=$('#search').value.toLocaleLowerCase('pt-BR');const items=debts.filter(d=>(filter==='Todas'||d.category===filter)&&[d.title,d.story,d.name].join(' ').toLocaleLowerCase('pt-BR').includes(query));$('#count').textContent=items.length+' histórias para conhecer';$('#filters').innerHTML=categories.map(c=>`<button class="filter ${c===filter?'active':''}" aria-pressed="${c===filter}" data-filter="${c}">${c}</button>`).join('');$('#cards').innerHTML=items.map(d=>{let rest=Math.max(0,d.value-d.paid);return `<article class="card"><div class="card-top"><span class="tag">${escapeHtml(d.category)}</span><span class="demo">DEMONSTRAÇÃO</span></div><h3>${escapeHtml(d.title)}</h3><p>${escapeHtml(d.story)}</p><div class="person">♡ História de ${escapeHtml(d.name)}</div><div style="margin-top:auto"><div class="amount-label">${rest?'Falta para quitar':'Meta atingida na simulação'}</div><div class="amount">${money(rest)}</div><button data-help="${d.id}" ${rest?'':'disabled'}>${rest?'Quero ajudar ↗':'✓ Dívida quitada na simulação'}</button></div></article>`}).join('')||'<p class="empty">Nenhuma história encontrada. Experimente outra busca ou categoria.</p>'}
$('#filters').onclick=e=>{if(e.target.dataset.filter){filter=e.target.dataset.filter;render()}};$('#search').oninput=render;$('#request').onclick=$('#request2').onclick=()=>$('#register').showModal();$('#cards').onclick=e=>{if(!e.target.dataset.help)return;selected=debts.find(d=>d.id===Number(e.target.dataset.help));$('#helpTitle').textContent=selected.title;const rest=Math.max(0,selected.value-selected.paid);$('#contribution').value=rest.toFixed(2);$('#contribution').max=rest.toFixed(2);$('#remaining').textContent='Faltam '+money(rest)+' para quitar esta dívida.';$('#contribute').showModal()};
$('#debtForm').onsubmit=e=>{e.preventDefault();const value=Number($('#value').value);if(!Number.isFinite(value)||value<1)return;debts.unshift({id:Date.now(),name:$('#name').value.trim()||'Pessoa anônima',title:$('#title').value.trim(),category:$('#category').value,value,paid:0,story:$('#story').value.trim()});save();filter='Todas';$('#search').value='';render();$('#register').close();e.target.reset();$('#dividas').scrollIntoView({behavior:'smooth'});notify('Dívida de demonstração cadastrada neste navegador.')};
$('#helpForm').onsubmit=e=>{e.preventDefault();const value=Number($('#contribution').value),rest=Math.round((selected.value-selected.paid)*100)/100;if(!Number.isFinite(value)||value<=0||value>rest)return;selected.paid=Math.round((selected.paid+value)*100)/100;save();render();$('#contribute').close();notify('Contribuição de '+money(value)+' simulada. Nenhum pagamento foi realizado.')};render();
